using StrataLint.Engine;
using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel;
internal sealed class CycleWordDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/CycleWord.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeDocument.Create(
        DefinitionDsl.GeneralHeader(
            "D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/CycleWord",
            "The literal three-block cycle list is a P02 Word on every original rim.",
            "actual-three-block-cycle-word-source-only",
            Anchor.ParseCanonical("mathlib/module/Mathlib.Order.UpperLower.CompleteLattice")),
        H("CycleWordDocument"),
        Blocks(
            Paragraph(Text("The selected AllMWheel, PathWord and sole FiniteProtectedDualWord authorities are immutable imports. This file adds no structure and generates no constructor/projection APIs. The full source-stated imported Word contract, including all eight field clauses, is quoted below with its source owner; no emitted telescope is asserted. Kernel/native/Scribe/Reg/gates/remote PR/dev acceptance remain due.")),
            SourceText("Immutable imported owner D5/S3/Geometry/FiniteProtectedDualWord; namespace D5.S3.Geometry.FiniteProtectedDualWord; variable {V : Type*} [Fintype V] [DecidableEq V]\nstructure Word (W : Finset V) (K : Family V) where\n  word : List (Symbol V)\n  supported : OriginalLabelTwoSum.Supported W K\n  pair_data : ∀ L v, Symbol.pair L v ∈ word →\n    L ∈ K ∧ insert v L ∈ K ∧ v ∉ L\n  critical_data : ∀ S, Symbol.critical S ∈ word → S ∈ K\n  partition : word.Pairwise (fun σ τ => Disjoint σ.faces τ.faces)\n  covers : ∀ s, s ∈ K ↔ ∃ i : Fin word.length, s ∈ (word.get i).faces\n  pair_dependency : ∀ («prefix» suffix : List (Symbol V)) L v,\n    word = «prefix» ++ Symbol.pair L v :: suffix →\n    ∀ T, T ⊂ insert v L → T ≠ L → ∃ σ ∈ «prefix», T ∈ σ.faces\n  critical_dependency : ∀ («prefix» suffix : List (Symbol V)) S,\n    word = «prefix» ++ Symbol.critical S :: suffix →\n    ∀ T, T ⊂ S → ∃ σ ∈ «prefix», T ∈ σ.faces"),
            Paragraph(Text("The construction distinguishes the following obligations: protected upward and whole-symbol H with every unexecuted critical; fill0 retaining ghosts, fill1 in every residue; Gamma iff and both obstruction residues; standalone B1/Q1; parent compiler; arbitrary history length distinct from width, markings, physical realizations and all-plane supplier; the arbitrary-plane supplier. In particular m=4 does not justify empty protection. No native selectors, green Reg result or local-fill success is claimed.")),
            Node("mem_cycleIndependentOn", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem mem_cycleIndependentOn (m : Nat) (hm : 3 ≤ m) (s : Finset (Label m)) :\n    s ∈ cycleIndependentOn m hm ↔ s ⊆ ground m ∧\n      ∀ e ∈ cycleEdges m hm, ¬ e ⊆ s", DescribeRole.Theorem, describeId: "mem-cycle-independent-on"),
            Node("cycleIndependentOn_lower", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem cycleIndependentOn_lower (m : Nat) (hm : 3 ≤ m)\n    {s t : Finset (Label m)} (hs : s ∈ cycleIndependentOn m hm) (ht : t ⊆ s) :\n    t ∈ cycleIndependentOn m hm", DescribeRole.Theorem, describeId: "cycle-independent-on-lower"),
            Node("mem_cycleFamily", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "@[simp] theorem mem_cycleFamily (m : Nat) (hm : 3 ≤ m) (s : Finset (Label m)) :\n    s ∈ facets (cycleIndependentOn m hm) ↔ s ∈ cycleIndependentOn m hm", DescribeRole.Theorem, describeId: "mem-cycle-family"),
            Node("cycleIndependentOn_decomposition", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem cycleIndependentOn_decomposition (m : Nat) (hm : 3 ≤ m) :\n    cycleIndependentOn m hm =\n      ((pathIndependentOn (cyclePath m hm) ∪\n        (pathIndependentOn (cyclePath m hm)).image (insert (firstLabel m hm))) ∪\n        (pathIndependentOn (cyclePathTail m hm)).image (insert (secondLabel m hm))) ∪\n        (pathIndependentOn (cyclePathLast m hm)).image (insert (lastLabel m))", DescribeRole.Theorem, describeId: "cycle-independent-on-decomposition"),
            Node("cycleWordData", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner.  Its literal word is cycleWord m hm. All eight fields are proved by the sorted first block and two actual immutable path Words, with base inclusions derived from cyclic endpoints. No new structure, constructor or projection authority is introduced.", "def cycleWordData (m : Nat) (hm : 3 ≤ m) :\n    Word (ground m) (facets (cycleIndependentOn m hm))", DescribeRole.Definition, describeId: "cycle-word-data"),
            Node("cycleWordData_word", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "@[simp] theorem cycleWordData_word (m : Nat) (hm : 3 ≤ m) :\n    (cycleWordData m hm).word = cycleWord m hm", DescribeRole.Theorem, describeId: "cycle-word-data-word"),
            Node("cycleWord_covers", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem cycleWord_covers (m : Nat) (hm : 3 ≤ m) (s : Finset (Label m)) :\n    s ∈ cycleIndependentOn m hm ↔\n      ∃ i : Fin (cycleWord m hm).length, s ∈ ((cycleWord m hm).get i).faces", DescribeRole.Theorem, describeId: "cycle-word-covers"),
            Node("cycleWord_critical_blocks", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem cycleWord_critical_blocks (m : Nat) (hm : 3 ≤ m) :\n    criticalFaces (cycleWord m hm) =\n      (pathCritical (cyclePathTail m hm)).image (insert (secondLabel m hm)) ∪\n      (pathCritical (cyclePathLast m hm)).image (insert (lastLabel m))", DescribeRole.Theorem, describeId: "cycle-word-critical-blocks"),
            Node("pathChosen_labelInterval", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem pathChosen_labelInterval (m lo n : Nat) (h : lo + n ≤ m + 1) (x : Label m) :\n    x ∈ FiniteIndependentPathGreedy.pathChosen (labelInterval m lo n h) ↔\n      lo + 1 ≤ x.val ∧ x.val < lo + n ∧ x.val % 3 = (lo + 1) % 3", DescribeRole.Theorem, describeId: "path-chosen-label-interval"),
            Node("tailWord_critical_formula", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem tailWord_critical_formula (m : Nat) (hm : 3 ≤ m) :\n    criticalFaces (tailWord m hm) =\n      if m % 3 = 2 then ∅ else {tailCritical m hm}", DescribeRole.Theorem, describeId: "tail-word-critical-formula"),
            Node("cycleWord_critical_formula", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem cycleWord_critical_formula (m : Nat) (hm : 3 ≤ m) :\n    criticalFaces (cycleWord m hm) =\n      if m % 3 = 0 then {labelsCongruent m 2 2, labelsCongruent m 0 3}\n      else if m % 3 = 1 then {labelsCongruent m 2 2}\n      else {insert (lastLabel m) (labelsCongruent m 0 3)}", DescribeRole.Theorem, describeId: "cycle-word-critical-formula"),
            Node("cycleCritical_eq_complements", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner.  cycleCritical is a dual target: every face on the right is complemented in the original fixed ground. Raw symbol criticals are given by cycleWord_critical_formula.", "theorem cycleCritical_eq_complements (m : Nat) (hm : 3 ≤ m) :\n    cycleCritical m hm =\n      (criticalFaces (cycleWord m hm)).image (fun s => ground m \\ s)", DescribeRole.Theorem, describeId: "cycle-critical-eq-complements"),
            Paragraph(Text("At m=5, cycleWord_critical_formula specializes to the exact raw-critical equation below. The residues 5 % 3 = 2, together with insert (lastLabel 5) (labelsCongruent 5 0 3) = {3,5} on Label 5, give this application of the general theorem. This is mathematical exposition, with no separate exported declaration or canonical Describe. The positive raw critical equation and its negative control excluding the raw face {1,3} follow from the same general formula. These applications introduce no exported theorem.")),
            SourceText("criticalFaces (cycleWord 5 (by omega)) =\n      {({(⟨3, by omega⟩ : Label 5), (⟨5, by omega⟩ : Label 5)} : Finset (Label 5))}"),
            Node("wheelRoot_mem_cycleDual", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner. ", "theorem wheelRoot_mem_cycleDual (m : Nat) (hm : 3 ≤ m) (s : Finset (Label m)) :\n    s ∈ wheelRoot m (by omega) ↔\n      s ⊆ ground m ∧ ground m \\ s ∉ cycleIndependentOn m hm", DescribeRole.Theorem, describeId: "wheel-root-mem-cycle-dual"),
            Node("cycleWord_wheelRoot_identity", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner.  This is an actual fixed-ground dual identity consumer. It does not construct a protected Contract, Sequence, Filling or Gamma endpoint.", "theorem cycleWord_wheelRoot_identity (m : Nat) (hm : 3 ≤ m) (s : Finset (Label m)) :\n    s ∈ wheelRoot m (by omega) ↔ s ⊆ ground m ∧\n      ¬ ∃ i : Fin (cycleWord m hm).length,\n        ground m \\ s ∈ ((cycleWord m hm).get i).faces", DescribeRole.Theorem, describeId: "cycle-word-wheel-root-identity"),
            Node("cycleWord_rawDual_eq_wheelRoot", "Literal SOURCE statement in namespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel; proof body is in the source owner.  This is an actual fixed-ground dual identity consumer. It does not construct a protected Contract, Sequence, Filling or Gamma endpoint.", "theorem cycleWord_rawDual_eq_wheelRoot (m : Nat) (hm : 3 ≤ m) :\n    rawDual (ground m) (facets (cycleIndependentOn m hm)) =\n      wheelRoot m (by omega)", DescribeRole.Theorem, describeId: "cycle-word-raw-dual-eq-wheel-root"))));
    private static DocumentBlock Node(string id, string prose, string sourceStatement,
        DescribeRole role, string? describeId = null) => Describe.Lean(DescribeId.Create(describeId ?? id), DeclarationHandle.Create(Prefix + id),
        H(id), role == DescribeRole.Definition ? StatementSource.WithoutFormula() : StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
        Blocks(SourceText(prose), SourceText(sourceStatement)), role);

    // TextRun is one line. Keep every quoted source line, including blank separators,
    // as typed text; this is commentary, never a substitute for a Lean projection.
    private static DocumentBlock SourceText(string value) => value.Contains('\n')
        ? new DocumentBlock.Section(H("Source text"), Blocks(Array.ConvertAll(
            value.Split('\n'), line => Paragraph(Text(line.Length == 0 ? "Definitions and proofs are in the paired Lean module." : line)))))
        : Paragraph(Text(value));
}
